import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { ApiError } from "../lib/api";
import {
  breakEvenBand,
  divergingColor,
  intervalText,
  nearest,
  niceTicks,
  roundNice,
  signed,
  symmetricScale,
  verdictSentence,
} from "../lib/analytics";
import fixture from "../test/analytics.fixture.json";
import type { AnalyticsReport, WinRate } from "../types";
import { AnalyticsView } from "./AnalyticsView";

// Generated by the backend's analytics.analyze() on 240 synthetic hands.
const REPORT = fixture as unknown as AnalyticsReport;

const rate = (over: Partial<WinRate>): WinRate => ({
  hands: 500,
  bb_per_100: 12,
  total_bb: 60,
  sd_bb: 10,
  se: 4,
  low: -30,
  high: 54,
  level: 0.95,
  method: "t",
  verdict: "unclear",
  p_value: 0.5,
  hands_for_precision: 15000,
  hands_to_confirm: 26_870,
  ...over,
});

describe("analytics helpers", () => {
  it("formats signed numbers with a real minus sign and no signed zero", () => {
    expect(signed(3.14)).toBe("+3.1");
    expect(signed(-2)).toBe("−2.0");
    expect(signed(-0.01)).toBe("0.0");
    expect(signed(12345, 0)).toBe("+12,345");
  });

  it("explains an unclear result as possibly variance and how many hands would settle it", () => {
    const s = verdictSentence(rate({}), 30);
    expect(s).toContain("−30 to +54 bb/100");
    expect(s).toContain("could still be variance");
    expect(s).toContain("about 27,000 more hands");
  });

  it("gives no interval or verdict below the minimum sample", () => {
    const r = rate({ hands: 12, verdict: "insufficient", low: null, high: null });
    expect(intervalText(r)).toBeNull();
    expect(verdictSentence(r, 30)).toContain("18 more before an interval is shown");
  });

  it("only calls a result winning when the interval excludes zero", () => {
    expect(verdictSentence(rate({ verdict: "winning", low: 3, high: 40 }), 30)).toContain("entirely above zero");
  });

  it("rounds, ticks, scales and searches sensibly", () => {
    expect(roundNice(2287)).toBe(2300);
    expect(niceTicks(-37, 112, 5)).toEqual([0, 50, 100]);
    expect(niceTicks(-80, 120, 5)).toEqual([-50, 0, 50, 100]);
    expect(nearest([{ n: 1 }, { n: 5 }, { n: 9 }], 6)).toBe(1);
    expect(breakEvenBand(10, 100)).toBeCloseTo(196);
    // One extreme cell does not set the scale.
    expect(symmetricScale([...Array(40).fill(1), 50])).toBe(1);
    expect(divergingColor(0, 1)).toBe("rgb(42, 51, 64)");
    expect(divergingColor(5, 1)).toBe("rgb(58, 127, 208)");
  });
});

describe("Stats view", () => {
  it("asks for a server profile when there is none", () => {
    render(<AnalyticsView handsVersion={0} />);
    expect(screen.getByTestId("analytics-none")).toHaveTextContent("hands saved on the server");
  });

  it("shows the win rate with its interval, verdict, chart, luck, trend, segments and grid", async () => {
    const load = vi.fn().mockResolvedValue(REPORT);
    const onShowHand = vi.fn();
    render(<AnalyticsView token="t" handsVersion={0} load={load} onShowHand={onShowHand} />);
    const summary = await screen.findByTestId("analytics-summary");
    expect(load).toHaveBeenCalledWith("t", { difficulty: null, last: null });
    expect(within(summary).getByTestId("verdict")).toHaveTextContent("Not yet clear");
    expect(within(summary).getByTestId("verdict-sentence")).toHaveTextContent("could still be variance");
    expect(screen.getByTestId("trend-verdict")).toHaveTextContent("Genuine improvement");
    expect(screen.getByTestId("trend-quality")).toBeInTheDocument();
    expect(screen.getByTestId("luck-verdict")).toHaveTextContent("normal range of luck");
    expect(within(screen.getByTestId("positions")).getAllByRole("row")).toHaveLength(3);
    expect(within(screen.getByTestId("opponents")).getByText("Beginner")).toBeInTheDocument();
    // 169 starting-hand cells, pairs on the diagonal.
    const grid = screen.getByTestId("hand-grid");
    const cells = within(grid).getAllByRole("button", { name: /^\w+: dealt/ });
    expect(cells).toHaveLength(169);
    expect(cells[0]).toHaveAccessibleName(/^AA:/);
    expect(cells[1]).toHaveAccessibleName(/^AKs:/);
    expect(cells[13]).toHaveAccessibleName(/^AKo:/);
    fireEvent.click(cells[0]);
    expect(screen.getByTestId("cell-detail")).toHaveTextContent("AA");
    fireEvent.click(within(grid).getByRole("button", { name: "Times dealt" }));
    expect(screen.getByTestId("grid-legend")).toHaveTextContent("times");
    // A table view of the chart exists for screen readers.
    expect(within(screen.getByTestId("bankroll")).getAllByRole("row").length).toBeGreaterThan(1);
  });

  it("refetches with the chosen filters", async () => {
    const load = vi.fn().mockResolvedValue(REPORT);
    render(<AnalyticsView token="t" handsVersion={0} load={load} />);
    await screen.findByTestId("analytics-summary");
    fireEvent.change(screen.getByRole("combobox"), { target: { value: "advanced" } });
    await waitFor(() => expect(load).toHaveBeenLastCalledWith("t", { difficulty: "advanced", last: null }));
    fireEvent.click(screen.getByRole("button", { name: "Last 100" }));
    await waitFor(() => expect(load).toHaveBeenLastCalledWith("t", { difficulty: "advanced", last: 100 }));
  });

  it("refetches when new hands are saved", async () => {
    const load = vi.fn().mockResolvedValue(REPORT);
    const { rerender } = render(<AnalyticsView token="t" handsVersion={0} load={load} />);
    await screen.findByTestId("analytics-summary");
    rerender(<AnalyticsView token="t" handsVersion={1} load={load} />);
    await waitFor(() => expect(load).toHaveBeenCalledTimes(2));
  });

  it("says when no hands match and keeps the last report on errors", async () => {
    const empty = { ...REPORT, hands: 0 };
    const load = vi.fn().mockResolvedValueOnce(empty);
    const { rerender } = render(<AnalyticsView token="t" handsVersion={0} pendingHands={2} load={load} />);
    expect(await screen.findByTestId("analytics-empty")).toHaveTextContent("2 finished hands are still waiting");
    load.mockResolvedValueOnce(REPORT).mockRejectedValueOnce(new ApiError("down", 503));
    rerender(<AnalyticsView token="t" handsVersion={1} load={load} />);
    await screen.findByTestId("analytics-summary");
    rerender(<AnalyticsView token="t" handsVersion={2} load={load} />);
    expect(await screen.findByRole("alert")).toHaveTextContent("storage is unavailable");
    expect(screen.getByTestId("analytics-summary")).toBeInTheDocument();
  });
});
